#!/usr/bin/env bash
set -eo pipefail
export HOME=/root
cd /opt/mesocyclonic-viewer
rm -f scripts/model/build_dataset.py tests/test_model_dataset.py; mkdir -p scripts/model/config tests
echo '' | base64 -d > 'scripts/model/config/model_selection.yaml'
echo 'ok: scripts/model/config/model_selection.yaml'
echo '' | base64 -d > 'scripts/model/indices.py'
echo 'ok: scripts/model/indices.py'
echo '' | base64 -d > 'scripts/model/labels.py'
echo 'ok: scripts/model/labels.py'
echo '' | base64 -d > 'scripts/model/features.py'
echo 'ok: scripts/model/features.py'
echo '' | base64 -d > 'scripts/model/kpis.py'
echo 'ok: scripts/model/kpis.py'
echo '' | base64 -d > 'scripts/model/models.py'
echo 'ok: scripts/model/models.py'
echo '' | base64 -d > 'pyproject.toml'
echo 'ok: pyproject.toml'
echo TRANSFER_DONE
